connect.lines:
with pick: http POST /v1/orders/{{orderId}}/pick | header=Content-Type: application/json | body={"items": {{items}}, "warehouse": {{warehouse}}}
with pack: box createFolder | operation.createFolderName== "Pack " + orderId | authentication.accessToken={{secrets.BOX_TOKEN}}
with label: http GET https://api.print-label.com/v1/templates/{{orderId}} | result=labelUrl: response.body.url
with dispatch: http POST /shipments | header=Content-Type: application/json | body={"orderId": {{orderId}}, "labelUrl": {{labelUrl}}, "status": "dispa tched"}

